def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = 8.0 if hp > 3 else 18.0
        return float(min(budget, base))

    prev_bids = []
    cindy_bid = None
    rich_threat = 0.0
    desperate_count = 0

    for opp in alive:
        obudget = float(opp.get('budget', 0.0))
        ohp = opp.get('hp', 0)
        onwd = opp.get('no_water_days', 0)
        if obudget > rich_threat:
            rich_threat = obudget
        if ohp <= 2 or onwd >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                bid = float(bid)
                prev_bids.append(bid)
                if bid > 80:
                    cindy_bid = bid

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= 17.0
    ample = supply >= 22.0
    urgent = hp <= 2 or no_water_days >= 1
    late_game = day >= 8

    bid = 0.0

    if urgent:
        target = max(72.0, highest_prev + 2.0)
        if cindy_bid is not None:
            target = max(target, cindy_bid + 2.0)
        bid = target
    elif scarcity:
        if cindy_bid is not None and rich_threat > 300:
            bid = max(58.0, cindy_bid + 1.5)
        else:
            bid = max(42.0, avg_prev + 3.0, highest_prev * 0.75)
    elif ample:
        bid = 9.0 if hp > 3 else 18.0
    else:
        bid = max(18.0, min(36.0, avg_prev * 0.45 + 8.0))

    if desperate_count >= 2 and not urgent:
        bid += 8.0
    if late_game and hp >= 4 and not scarcity:
        bid -= 4.0

    reserve = 0.0
    if hp > 3:
        reserve = DAILY_SALARY * 2
    elif hp > 1:
        reserve = DAILY_SALARY

    max_affordable = budget - reserve
    if urgent:
        max_affordable = budget
    if max_affordable < 0:
        max_affordable = min(budget, DAILY_SALARY * 0.5)

    bid = min(bid, max_affordable, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday's trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: when supply is low, competition for survival increases
    # Map supply (15..25) to a pressure factor (0..1)
    if MAX_SUPPLY == MIN_SUPPLY:
        pressure = 0.5
    else:
        pressure = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    # Lower supply => higher pressure, so invert
    pressure = 1.0 - max(0.0, min(1.0, pressure))

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Base bid level: target around 0.55 salary at comfortable HP, higher at low HP
    if my_hp <= 2:
        base = DAILY_SALARY * 0.9
    elif my_hp <= 4:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # If someone previously bid extremely high, avoid mirroring; instead outbid typical bids
    # while staying under the extreme to preserve budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Alex showed survival with high max bids; still we don't need to match.
        base = max(base, DAILY_SALARY * 0.65)

    # Adjust for supply pressure: low supply => bid more
    bid = base * (0.85 + 0.3 * pressure)

    # Safety: never bid more than budget
    bid = min(bid, my_budget)

    # If budget is tiny, bid as much as possible to avoid wasting turns
    if my_budget <= DAILY_SALARY * 0.25:
        bid = my_budget

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    previous_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            previous_bids.append(prev['bid'])
    supply = day_context['supply']
    supply_int = int(supply)
    base_bid = DAILY_SALARY * 0.5
    if previous_bids:
        avg_prev = sum(previous_bids) / len(previous_bids)
        bid = max(base_bid, avg_prev + 1.0)
    else:
        bid = base_bid
    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
        bid = max(bid, DAILY_SALARY * 0.8)
    bid = min(bid, my_status['budget'])
    bid = min(bid, DAILY_SALARY * 0.95)
    return max(0, bid)
